PREFIX : <http://www.semanticweb.org/ontologies/2026/energy-system#>
SELECT ?asset ?powerMW WHERE {
  { ?asset a :HydroPowerPlant } UNION { ?asset a :PumpedStorageHydro } UNION { ?asset a :EnergyStorage }
  ?asset :hasRatedActivePowerMW ?powerMW .
}

PREFIX : <http://www.semanticweb.org/ontologies/2026/energy-system#>
SELECT ?consumer ?powerMW WHERE {
  { ?consumer a :IndustrialConsumer } UNION { ?consumer a :ResidentialConsumer } UNION { ?consumer a :EnergyConsumer }
  ?consumer :hasVoltageLevelKV 110.0 ;
            :hasRatedActivePowerMW ?powerMW .
  FILTER (?powerMW > 100.0)
}
